/** Target solo RMS (dBFS) per group; style-specific overrides below. */
export const MIX_TARGETS = {
  default: { chords: -19.5, bass: -21, drums: -18, melody: -23 },
  'classical-piano': { chords: -19, melody: -23 },
  ambient: { chords: -21, melody: -23 },
  cinematic: { drums: -21 },
  shoegaze: { chords: -17, melody: -25 },
  'hard-rock': { chords: -17, drums: -17 },
  'indie-rock': { chords: -18, drums: -17.5 },
  pop: { drums: -17 },
  house: { drums: -16.5, chords: -20.5 },
  jazz: { drums: -24, chords: -20, melody: -22 },
  folk: { drums: -29, melody: -22.5 },
  trap: { bass: -17.5, drums: -18 },
  lofi: { chords: -19, drums: -19 },
};

export const LOUDNESS_TARGET = -15;   // full-mix RMS, dBFS

export function mixFor(styleId) {
  const m = { chords: 0, bass: 0, drums: 0, melody: 0, master: 0, ...MIX[styleId] };
  return { points: m.melody, ...m };    // 'points' = level of the point drums
}
